const rows = $input.all().map(i => i.json);
const latest = rows[rows.length - 1];
const cells = Object.entries(latest).map(([k, v]) => `<tr><td style="padding:6px 14px;border:1px solid #ddd;font-weight:600">${k}</td><td style="padding:6px 14px;border:1px solid #ddd">${v}</td></tr>`).join('');
const html = `<h2>Daily KPI Report</h2><table style="border-collapse:collapse;font-family:Arial">${cells}</table><p style="color:#888;font-size:12px">Sent automatically by n8n.</p>`;
return [{ json: { html } }];
